/// <summary>
/// Abstract class for orders to create shipment and laod
/// </summary>
abstract class METOrderShipmentLoadCreation
{
    SalesTable          salesTable;
    InventTransferTable inventTransferTable;

}

Method.Source:
/// <summary>
/// Construct method to initiate the subclass
/// </summary>
/// <param name = "_orderTransactionType">Transcation type</param>
/// <param name = "_orderNum">Order number</param>
/// <returns>METOrderShipmentLoadCreation</returns>
public static METOrderShipmentLoadCreation construct(METOrderTransactionType _orderTransactionType, METOrderReference       _orderNum)
{
    METOrderShipmentLoadCreation        metOrderShipmentLoadCreation;

    if (_orderTransactionType == METOrderTransactionType::SalesOrder)
    {
        metOrderShipmentLoadCreation = new METOrderShipmentLoadCreation_SalesOrder(SalesTable::find(_orderNum));
    }
    else if (_orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        metOrderShipmentLoadCreation = new METOrderShipmentLoadCreation_TransferOrder(InventTransferTable::find(_orderNum));
    }
    else
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return metOrderShipmentLoadCreation;
}

/// <summary>
/// Create new shipment and load
/// </summary>
/// <param name = "_createShipment">Boolean flag</param>
/// <param name = "_skipShipmentLinesCreation">Boolean flag</param>
public void createShippmentLoad(boolean       _createShipment,
                                boolean       _skipShipmentLinesCreation)
{
    METSalesOrderShipmentLoadHeader  metSalesOrderShipmentLoadHeader = this.findOrCreateOpenShipment(_createShipment);

    if (metSalesOrderShipmentLoadHeader.RecId)
    {
        if (_skipShipmentLinesCreation == false)
        {
            this.createShipmentLines(metSalesOrderShipmentLoadHeader);
        }

        MetLoadId       loadId = this.consolidateShipmentAndCreateLoads(_createShipment);

        info(strFmt("@MET:ShipmentUpdated", metSalesOrderShipmentLoadHeader.ShipmentId));
        info(strFmt("@MET:LoadUpdated", loadId));
    }
}
